---
name: status-window-patterns
description: >-
  상태창 HTML을 실제로 짤 때 가져다 쓰는 코드 뼈대와 조각 모음(골격, 탭, 캐릭터 카드, 게이지, 기억 패널, 챕터, 설정집, 행동
  큐, 세력별 성장 시스템).
---
# 상태창 코드 패턴

아래 코드는 실제로 출시된 상태창들에서 핵심만 줄여 옮긴 것이다. 코드 안의 이름, 소속, 라벨, 색 값은 전부 **예시**이니 작품에 맞게 바꾼다. 실제로 줄 때는 조각을 이어 붙여 **완성된 HTML 한 덩어리**로 준다. `(제안)` 표시는 실전에서 아직 써 보지 않았고 공식 문서 권장이나 새로 덧붙인 방식이다.

## 1. 핵심 골격 (CSS 토큰 + 앱 구조)
```html
<!-- {작품} 상태창 v1 (statusView 고급 모드: <body> 내부만) | 탭: 메인/캐릭터/기억
  읽는 변수(N): Turn·날짜·시간대·장소·…·'{이름} 기억'×K·'{이름} 관계'×K
  보내는 명령(SYSTEM_CMD 내부): 기억기록:이름:내용 / 메모리압축:이름 / … | TOD·REL_STAGES는 규칙 노드 값과 동일 -->
<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;700&family=Noto+Serif+KR:wght@600;900&display=swap" rel="stylesheet">
<style>
/* ===== 테마 토큰: {테마명} ===== */
:root{
  --bg:#eaf4fd; --bg2:#dcecf9; --card:#fff; --card-h:#f2f8ff;
  --bdr:#cde1f2; --bdr2:#a4c5e3;
  --acc:#2f7fc4; --acc2:#6f98bd; --pt:#e0503c;   /* 강조 / 보조 / 포인트 */
  --txt:#17222f; --txt2:#51647a; --txt3:#6f849a;
}
*{margin:0;padding:0;box-sizing:border-box}
button{color:inherit;-webkit-text-fill-color:currentColor;font-family:inherit}
#modal,#toast{color:var(--txt);font-family:'Noto Sans KR',sans-serif}  /* .app 밖 요소 */
::-webkit-scrollbar{width:0;display:none} *{scrollbar-width:none;-ms-overflow-style:none}
.app{height:100vh;display:flex;flex-direction:column;overflow:hidden;background:var(--bg);
  color:var(--txt);font-family:'Noto Sans KR',sans-serif;font-size:14px;line-height:1.6}
header{flex-shrink:0;padding:10px 14px 9px;border-bottom:1px solid var(--bdr)}
.hdr{display:flex;align-items:center;gap:12px}
.logo{font-family:'Noto Serif KR',serif;font-weight:900;font-size:22px;letter-spacing:2px;color:var(--acc)}
.logo em{font-style:normal;color:var(--pt)}
.hud{flex:1;min-width:0;display:flex;flex-direction:column;gap:6px}
.hud-row{display:flex;gap:6px;flex-wrap:wrap;min-width:0}
.chip{background:var(--card);border:1px solid var(--bdr);border-radius:4px;padding:3px 9px;
  font-size:12px;color:var(--txt2);white-space:nowrap;display:flex;align-items:center}
.chip b{color:var(--txt);font-weight:500;margin-left:5px;overflow:hidden;text-overflow:ellipsis}
.tod{display:flex;background:var(--card);border:1px solid var(--bdr);border-radius:4px;padding:3px 6px}
.tod .seg{font-size:11px;color:var(--txt3);padding:0 6px;letter-spacing:1px}
.tod .seg+.seg{border-left:1px solid var(--bdr)} .tod .seg.on{color:var(--acc);font-weight:700}
.tab-nav{flex-shrink:0;display:flex;border-bottom:1px solid var(--bdr);background:var(--bg2)}
.tab-btn{flex:1;background:none;border:none;color:var(--txt3);cursor:pointer;font-size:13.5px;
  font-weight:700;padding:11px 0 9px;border-bottom:2px solid transparent;transition:.15s}
.tab-btn.active{color:var(--acc);border-bottom-color:var(--acc)}
.body{flex:1;min-height:0;position:relative;overflow:hidden}
.panel{display:none;height:100%;flex-direction:column} .panel.show{display:flex}
.scroll{flex:1;min-height:0;overflow-y:auto;padding:14px}
.sec-title{font-size:11.5px;font-weight:700;letter-spacing:2px;color:var(--acc);margin:2px 0 8px;
  display:flex;align-items:center;gap:8px}
.sec-title::after{content:'';flex:1;height:1px;background:linear-gradient(90deg,var(--bdr2),transparent)}
.card{background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:12px 14px}
.empty{color:var(--txt3);text-align:center;padding:18px 0;font-size:13px}
.spacer{height:14px}
#toast{position:fixed;left:50%;bottom:84px;transform:translateX(-50%);opacity:0;pointer-events:none;transition:.2s;z-index:60;
  background:rgba(23,34,47,.94);color:#fff;border-radius:20px;padding:7px 16px;font-size:12.5px} #toast.show{opacity:1}
</style>

<div class="app">
  <header><div class="hdr">
    <div><img id="logo-img" alt="" style="display:none;height:76px"><div class="logo" id="logo-txt">작품<em>명</em></div></div>
    <div class="hud">
      <div class="hud-row"><div class="chip">📅<b id="hud-date">-</b></div><div class="tod" id="hud-tod"></div></div>
      <div class="hud-row"><div class="chip">📍<b id="hud-loc">-</b></div><div class="chip">Turn<b id="hud-turn">-</b></div></div>
    </div>
  </div></header>
  <nav class="tab-nav">
    <button class="tab-btn active" data-tab="main" onclick="showTab('main')">메인</button>
    <button class="tab-btn" data-tab="char" onclick="showTab('char')">캐릭터</button>
    <button class="tab-btn" data-tab="mem" onclick="showTab('mem')">기억</button>
  </nav>
  <div class="body">
    <section class="panel show" id="p-main"><div class="scroll">
      <div class="sec-title">현재 상황</div><div class="card"><div id="situ-text" style="white-space:pre-wrap">대기중...</div></div>
      <div class="spacer"></div><div class="sec-title">선택지</div><div id="choice-list"></div>
    </div></section>
    <section class="panel" id="p-char">…</section>
    <section class="panel" id="p-mem">…</section>
  </div>
  <div id="queue-bar">…</div>   <!-- 8절 -->
</div>
<div id="toast"></div>
```

## 2. 스크립트 기본부 (플래그, 변수 읽기, 유틸)
```js
/* ===== JS-0: 설정 플래그 ===== */
var USE_DUMMY  = false;                       // 테스트본만 true
var REL_STAGES = ['미대면','초면','아는 사이','친근','썸','연인'];  // 규칙 노드와 동일
var TOD        = ['아침','낮','저녁','심야'];
var LOGO_URL   = '';                          // 비우면 텍스트 로고
/* ===== JS-2: 변수 읽기 + 더미 폴백 ===== */
var lastData = null;
function getVar(d, key){
  if(!d || !d.getValue) return null;
  try{
    var v = d.getValue(key); if(v != null) return v;
    v = d.getValue('var_' + key); if(v != null) return v;
    var all = d.getObject ? d.getObject() : null; if(!all) return null;
    var t = key.normalize('NFC');
    for(var k in all){ var n = k.normalize('NFC'); if(n === t || n === 'var_' + t) return all[k]; }
  }catch(e){}
  return null;
}
var DUMMY = {};   // 예: {'날짜':'10월 14일 (수)','시간대':'저녁','선택지':'A|B|C'}
function gv(key){
  var v = getVar(lastData, key);
  if(v != null && v !== '') return v;
  return (USE_DUMMY && DUMMY[key] != null) ? DUMMY[key] : null;
}
/* ===== JS-3: 유틸 ===== */
function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;')
  .replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function setText(id, v, def){ var el = document.getElementById(id);   // 템플릿 규칙: 0/false/빈 문자열도 기본값
  if(el) el.innerText = v || def || '-'; }   // 숫자 0을 보여야 하면 String(v)로 넘긴다
function toast(msg){ var t = document.getElementById('toast'); t.innerText = msg; t.classList.add('show');
  clearTimeout(toast._tm); toast._tm = setTimeout(function(){ t.classList.remove('show') }, 1600); }
function sendSafe(msg){   // 버튼 클릭에서만 호출. 정식 턴(크레딧 차감)
  try{ if(typeof sendMessage === 'function'){ sendMessage(msg); toast('전송: ' + msg.slice(0,24).replace(/\n/g,' ')); }
       else toast('(미연결) ' + msg.slice(0,24)); }catch(e){ toast('전송 실패'); }
}
function stageOf(v, stages){      // 숫자·숫자문자열·라벨 → 인덱스, 불가 = -1
  if(v == null || v === '') return -1; v = String(v).trim();
  if(/^-?\d+$/.test(v)) return Math.max(0, Math.min(stages.length - 1, parseInt(v)));
  return stages.indexOf(v);
}
```

## 3. 탭 전환, HUD, 시간대 세그먼트, 로고 대체
```js
function showTab(id){
  ['main','char','mem'].forEach(function(t){ document.getElementById('p-' + t).classList.toggle('show', t === id); });
  document.querySelectorAll('.tab-btn').forEach(function(b){ b.classList.toggle('active', b.getAttribute('data-tab') === id); });
  if(id === 'mem') renderMem();
}
function renderHud(){
  setText('hud-date', gv('날짜')); setText('hud-loc', gv('장소')); setText('hud-turn', gv('Turn'));
  var cur = gv('시간대'), box = document.getElementById('hud-tod'); box.innerHTML = '';
  TOD.forEach(function(s){ var d = document.createElement('span');
    d.className = 'seg' + (s === cur ? ' on' : ''); d.innerText = s; box.appendChild(d); });
  var li = document.getElementById('logo-img'), lt = document.getElementById('logo-txt');
  if(LOGO_URL && li.getAttribute('src') !== LOGO_URL){
    li.onload  = function(){ li.style.display = 'block'; lt.style.display = 'none'; };
    li.onerror = function(){ li.style.display = 'none'; lt.style.display = ''; };
    li.src = LOGO_URL;
  }
}
```

## 4. 캐릭터 데이터, 카드 그리드, 상세
(캐릭터 개인색은 쓰지 않는다. `cstyle`은 테마 강조색 `THEME_COL`로 `--c --rgb --ink --on`을 채운다. `THEME_COL`은 `:root`의 `--acc`와 같은 값으로 `JS-0`에 둔다.)
```js
// 예시 데이터: 실제 작품의 등장인물로 바꾼다
var CHARS = [
 {name:'하린', full:'윤하린', cardImg:'', detailImg:'',
  org:'예시 소속', role:'예시 직책', age:'22세', speech:'존댓말', look:'흑발 · 갈색 눈',
  traits:['…'], rep:[['소속','…'],['마을','…']]}
];
function rgbOf(h){ h = h.replace('#',''); return parseInt(h.substr(0,2),16)+','+parseInt(h.substr(2,2),16)+','+parseInt(h.substr(4,2),16); }
function onOf(h){ var r=parseInt(h.substr(1,2),16), g=parseInt(h.substr(3,2),16), b=parseInt(h.substr(5,2),16);
  return (0.299*r + 0.587*g + 0.114*b) / 255 > 0.62 ? '#17222f' : '#ffffff'; }
var THEME_COL = '#2f7fc4';   // :root --acc와 같게
function cstyle(c){ var col = c.col || THEME_COL; return '--c:'+col+';--rgb:'+rgbOf(col)+';--ink:'+(c.ink||col)+';--on:'+onOf(col); }
function artHtml(c, kind){   // 이니셜 아바타 위에 이미지. 실패하면 이미지 숨김
  var src = kind === 'detail' ? (c.detailImg || c.cardImg) : c.cardImg;
  return '<div class="av"><span>' + esc(c.name.charAt(0)) + '</span></div>' +
    (src ? '<img src="' + esc(src) + '" alt="" onerror="this.style.display=\'none\'">' : '');
}
function pipsHtml(idx, total){ var s = '';
  for(var i = 0; i < total; i++) s += (i < idx ? '●' : '<span class="off">●</span>');
  return '<span class="pips">' + s + '</span>'; }
function renderChars(){
  var g = document.getElementById('char-grid'); g.innerHTML = '';
  CHARS.forEach(function(c, i){
    var r = stageOf(gv(c.name + ' 관계'), REL_STAGES), d = document.createElement('div');
    d.className = 'cc'; d.setAttribute('style', cstyle(c));
    d.innerHTML = '<div class="cc-img">' + artHtml(c) +
      (r >= 0 ? '<div class="cc-rel">' + pipsHtml(r, REL_STAGES.length - 1) + '</div>' : '') + '</div>' +
      '<div class="cc-info"><div class="cc-name">' + esc(c.name) + '</div><div class="cc-role">' + esc(c.role) + '</div></div>';
    d.onclick = function(){ openDetail(i); }; g.appendChild(d);
  });
}
function kv(k, v){ return '<div class="kv"><div class="k">' + esc(k) + '</div><div class="v">' + esc(v) + '</div></div>'; }
```
```css
.char-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(104px,1fr));gap:10px}
.cc{background:var(--card);border:1px solid var(--bdr);border-radius:9px;overflow:hidden;cursor:pointer;transition:.15s}
.cc:hover{border-color:var(--ink);transform:translateY(-2px)}
.cc-img{position:relative;aspect-ratio:3/4;overflow:hidden}
.cc-img img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:top}
.av{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font:900 38px 'Noto Serif KR',serif;
  color:var(--on);background:linear-gradient(160deg,rgb(var(--rgb)),rgba(var(--rgb),.72))}
.cc-rel{position:absolute;left:0;right:0;bottom:0;text-align:center;background:linear-gradient(0deg,rgba(10,16,26,.78),transparent)}
.cc-info{padding:7px 6px 8px;text-align:center;border-top:2px solid var(--ink)}
.pips{font-size:9px;letter-spacing:2px;color:var(--acc)} .pips .off{opacity:.3}
.hero{position:relative;aspect-ratio:16/11;border-radius:10px;overflow:hidden}  /* 아래 .ovl 그라데이션 위 흰 글씨 */
```
- 상세 화면에서는 긴 텍스트를 자르지 않고 전부 보여 준다(`white-space:pre-wrap`).
- 상세 화면: 목록 `scroll`을 숨기고 상세 `scroll`을 보여 준다(`← 목록` 버튼). 히어로 → 관계 줄(라벨+pips) → `상세` 아코디언(kv 행, 특징 목록, 주변 평판) → `기억 보기 ›` 버튼(기억 탭으로 이동) 순서다.
- 인물이 20명 이상이면(실전 예: 60명이 넘는 작품) 이렇게 한다: 왼쪽 사이드에 그룹(접기)과 소속, 위에 검색창(`input`과 `compositionend` 둘 다 잡기), `전체 N명` 표시.

## 5. 게이지와 단계 표시
```js
var rep = Math.max(0, Math.min(5, parseInt(gv('평판')) || 0));
setText('st-stars', '★'.repeat(rep) + '☆'.repeat(5 - rep));
// (제안) 게이지 바: 연속 수치. 공식 문서 권장 방식
function gauge(id, v, min, max, warnAt){
  var pct = Math.max(0, Math.min(100, ((parseFloat(v) || 0) - min) / (max - min) * 100));
  var f = document.getElementById(id); if(!f) return;
  f.style.width = pct + '%'; f.classList.toggle('hot', warnAt != null && pct >= warnAt);
}
```
```css
.gauge{height:8px;background:var(--bg2);border-radius:4px;overflow:hidden}
.gauge > i{display:block;height:100%;width:0;background:var(--acc);transition:width .4s}
.gauge > i.hot{background:var(--pt)}
```

## 6. 기억 패널 (캐릭터 사이드 탭)
```js
// 변수 '{이름} 기억' = "Turn^내용 | Turn^내용"  (압축: "Turn^압축됨 · 요약")
function parseMem(raw){ var out = []; if(!raw) return out;
  String(raw).split(/\s\|\s/).forEach(function(seg, i){ seg = seg.trim(); if(!seg) return;
    var m = seg.match(/^([^\^]*)\^([\s\S]*)$/), turn = m ? m[1].trim() : '', txt = m ? m[2].trim() : seg;
    var comp = /^압축됨/.test(txt); if(comp) txt = txt.replace(/^압축됨\s*[·:\-]?\s*/, '');
    out.push({turn:turn, txt:txt, comp:comp, idx:i}); });
  return out; }
var memChar = CHARS[0].name;
function renderMem(){
  var cur = CHARS.filter(function(c){ return c.name === memChar })[0] || CHARS[0];
  var side = document.getElementById('mem-side'); side.innerHTML = '';
  CHARS.forEach(function(c){ var b = document.createElement('button');
    b.className = 'ms-btn' + (c === cur ? ' on' : ''); b.setAttribute('style', cstyle(c));
    b.innerHTML = '<span class="n">' + esc(c.name) + '</span><span class="c">' + parseMem(gv(c.name + ' 기억')).length + '건</span>';
    b.onclick = function(){ memChar = c.name; renderMem(); }; side.appendChild(b); });
  var rows = parseMem(gv(cur.name + ' 기억')).sort(function(a, b){
    return ((parseInt(b.turn) || 0) - (parseInt(a.turn) || 0)) || (b.idx - a.idx); });   // 최신순
  var list = document.getElementById('mem-list'); list.innerHTML = rows.length ? '' : '<div class="empty">기록된 기억 없음</div>';
  rows.forEach(function(e){ var d = document.createElement('div');
    d.className = 'mi' + (e.comp ? ' comp' : ''); d.setAttribute('style', cstyle(cur));
    d.innerHTML = '<div class="mi-head"><span class="mi-turn">T' + esc(e.turn || '?') + '</span>' +
      (e.comp ? '<span class="mi-comp">압축</span>' : '') + '</div><div class="mi-txt">' + esc(e.txt) + '</div>';
    list.appendChild(d); });
}
function confirmMemRecord(txt){   // 모달 확인 버튼
  txt = txt.replace(/\s*\n\s*/g, ' ').replace(/\|/g, '/').replace(/\^/g, '').trim();
  if(!txt){ toast('내용을 입력하세요'); return; }
  enqueue('memory', '기억 · ' + memChar, '기억기록:' + memChar + ':' + txt);
}
// 압축은 확인 모달("되돌릴 수 없어요") 뒤에 enqueue('memory','압축 · '+memChar,'메모리압축:'+memChar)
```
```css
.mem-wrap{flex:1;min-height:0;display:flex}
.mem-side{width:92px;flex-shrink:0;overflow-y:auto;background:var(--bg2);border-right:1px solid var(--bdr);
  padding:8px 6px;display:flex;flex-direction:column;gap:6px}
.ms-btn{background:var(--card);border:1px solid var(--bdr);border-left:3px solid var(--ink);border-radius:7px;padding:8px 9px;text-align:left}
.ms-btn.on{background:rgba(var(--rgb),.30);border-color:var(--ink)}
.mi{background:var(--card);border:1px solid var(--bdr);border-left:3px solid var(--ink);border-radius:8px;padding:10px 13px;margin-bottom:9px}
.mi.comp{border-left-style:dashed}
```

## 7. 챕터 트래커 (실전 예: 메인 챕터를 차례로 여는 작품의 스토리 탭 요약)
```js
var STORY_DB = [
  {id:'ch1', type:'메인', chapter:1, title:'1장: …', epigraph:'', img:'', triggerKeyword:'◈MCH1◈', req:'언제나 가능'},
  {id:'ch2', type:'메인', chapter:2, title:'2장: …', triggerKeyword:'◈MCH2◈', req:'1장 클리어'}
];
function chapterNums(){   // 변수가 진실의 원천. 없으면 null
  var p = parseInt(gv('진행챕터')), c = parseInt(gv('클리어챕터'));
  if(isNaN(p) && isNaN(c)) return null; return {prog: p || 0, clear: c || 0};
}
function storyState(st){ if(st.type !== '메인') return 'open';
  var cn = chapterNums() || {prog:0, clear:0};
  return st.chapter <= cn.clear ? 'cleared' : st.chapter === cn.clear + 1 ? 'open' : 'locked'; }
// 카드: banner(16/6)+오버레이(제목·epigraph·'발동 조건: '+req)+badge(OPEN/LOCKED/CLEAR/진행중)
// locked → toast('조건 미충족'), cleared → 결산 모달(분기기록 슬롯 n 파싱 'k:v/k:v'),
// open → 진행 중 챕터가 있으면 차단, 없으면 확인 모달 → actQueue에 {type:'story', msg: triggerKeyword} 하나만
function parseBranches(){ var out = {}; String(gv('분기기록') || '').split('|').forEach(function(seg, i){
  var s = seg.trim(); if(s) out[i + 1] = s.split('/').map(function(x){ return x.trim() }).filter(Boolean); }); return out; }
```
