- 일정형(실전 예: 날짜와 행사 일정이 중요한 작품): `EVENTS`(`date:'MM-DD'` 매년, `'YYYY-MM-DD'` 일회성, `end` 기간)와 `날짜`로 가장 가까운 일정을 `D-n` 배너로. 누르면 확인 모달 → `일정점프:이름:M월 D일` 큐(전용 규칙 없이 LLM 해석, style 6절).

## 8. 행동 큐 바와 SYSTEM_CMD 전송
```html
<div id="queue-bar">
  <div class="qbar-head"><span>행동 큐 <b id="qbar-count">0</b></span><button class="qbar-clear" onclick="clearQueue()">비우기</button></div>
  <div id="qbar-items"></div>
  <div class="qbar-row"><textarea id="qbar-input" rows="1" placeholder="지문·대사 입력 (선택)"></textarea>
    <button class="qbar-send" onclick="flushTurn()">전송 ▶</button></div>
</div>
```
```js
var actQueue = [];   // {type, label, msg}
function enqueue(type, label, msg){ actQueue.push({type:type, label:label, msg:msg}); renderMain(); }
function pickChoice(c){   // 선택지는 1개만, 다시 누르면 해제
  var had = actQueue.some(function(q){ return q.type === 'choice' && q.label === c });
  actQueue = actQueue.filter(function(q){ return q.type !== 'choice' });
  if(!had) actQueue.push({type:'choice', label:c, msg:c}); renderMain(); }
function renderChoices(){
  var box = document.getElementById('choice-list'); box.innerHTML = '';
  var opts = String(gv('선택지') || '').split('|').map(function(s){ return s.trim() }).filter(Boolean);
  if(!opts.length){ box.innerHTML = '<div class="empty">선택지 없음</div>'; return; }
  opts.forEach(function(c, i){ var b = document.createElement('button');
    b.className = 'choice-btn' + (actQueue.some(function(q){ return q.type === 'choice' && q.label === c }) ? ' queued' : '');
    b.innerHTML = '<span class="num">' + (i + 1) + '</span><span>' + esc(c) + '</span>';
    b.onclick = function(){ pickChoice(c); }; box.appendChild(b); });
}
function renderQueue(){ var bar = document.getElementById('queue-bar'), box = document.getElementById('qbar-items');
  document.getElementById('qbar-count').innerText = actQueue.length; bar.classList.toggle('has', actQueue.length > 0); box.innerHTML = '';
  actQueue.forEach(function(q, i){ var d = document.createElement('div'); d.className = 'q-chip q-' + q.type;
    d.innerHTML = '<span>' + esc(q.label) + '</span><button class="q-del">✕</button>';
    d.lastChild.onclick = function(){ actQueue.splice(i, 1); renderMain(); }; box.appendChild(d); }); }
function flushTurn(){
  var ta = document.getElementById('qbar-input'), prose = ta.value.trim();
  if(!prose && !actQueue.length){ toast('입력하거나 행동을 추가하세요'); return; }
  var out = prose;
  if(actQueue.length) out = (prose ? prose + '\n' : '') + '---SYSTEM_CMD---\n' +
    actQueue.map(function(q){ return q.msg }).join('\n') + '\n---END_CMD---';
  sendSafe(out); ta.value = ''; actQueue = []; renderMain();
}
```
- 큐 칩 테두리 색은 `q-{type}` 클래스로 나눈다(선택지는 강조색, 기억은 포인트색). `.qbar-head`는 `#queue-bar.has`일 때만 보인다.
- 확인 모달 하나를 같이 쓴다: `openConf(title,msg,okLabel,cb)`, `position:fixed;inset:0`, `.open`이면 `display:flex`.

## 9. 설정집(코덱스) 페이지
```js
// 블록 타입: prose(본문, hl 강조어, 【제목】 줄은 헤더) / terms([{k,v}]) / list(['…']) / table(head, rows, note)
// 예시 데이터: 분류와 항목은 작품 설정으로 바꾼다
var GUIDE_CATS = ['세계','세력','인물관계'];
var GUIDE_DB = [
  {cat:'세계', title:'세계관', type:'prose', always:true, hl:['예시 세력'], body:'【 세계 제목 】\n\n본문…'},
  {cat:'세계', title:'연표', type:'terms', items:[{k:'시대', v:'설명'}]},
  {cat:'세력', title:'세력 제도', type:'list', items:['…','…']},
  {cat:'세력', title:'계급', type:'table', head:['계급','조건'], rows:[['…','…']], note:'…'}
];
function guideBody(g){ /* type별 분기: table → <table class="g-tbl">(+g-note) / terms·list → g-term(k,v)·g-li /
  prose → esc 후 hl 단어를 <b class="g-hl">로(정규식 이스케이프), 줄머리 【…】는 <div class="g-h"> 헤더로 */ }
// 렌더: 사이드에 GUIDE_CATS → 선택 분류의 항목. always:true는 펼친 채로, 나머지는 아코디언(.guide-item.open)
```
- 트리형(`GUIDE_TREE` 중첩 children과 ▶ 토글)은 항목이 깊게 계층화될 때만 쓴다.
- 해금형 설정집(제안): 항목에 `req:'클리어챕터>=2'` 같은 조건을 두고, 변수값으로 잠금/해금을 표시한다. 조건 판정은 반드시 변수로 한다(로컬 저장 불가).

