## 11. 루트/세력별 성장 탭 (실전 예: 세력이 둘인 무협 작품, 세력마다 다른 상태창)
```js
// [세력 A] 기술 슬롯형 — 변수: 무기종류, 습득기술("a,b,c"), 슬롯 1~4, 휴식여부(true/false)
var SKILL_DB = { '예시검': { '예시 검술':{cost:20, dmg:'120%', desc:'…'} } };   // 예시 데이터
function renderSlots(d){
  var w = SKILL_DB[gv('무기종류')] || {}, resting = String(gv('휴식여부')).toLowerCase() === 'true';
  var slots = [1,2,3,4].map(function(i){ return gv('슬롯 ' + i) || ''; });
  // 슬롯 카드: 빈칸은 점선, 채움은 이름+비용. 습득 기술 카드의 [장착]은 resting일 때만 활성
  // 장착 → 슬롯 고르기 팝업 → enqueue('cmd','기술장착: 슬롯'+n+' ← '+sk,'기술장착:'+n+':'+sk) (같은 기술이 다른 슬롯에 있으면 '기술해제:'+j 함께)
}
// [세력 B] 경지 특성 트리형 — 변수: '{n}성특성'(선택명), '{n}성해금'(true/false)
var TREE = [ {tier:'1星', name:'1단계', choices:[{name:'특성 A', effect:'출혈 5%'},{name:'특성 B', effect:'맨손 +20%'}]} ];   // 예시 데이터
function renderTree(){
  TREE.forEach(function(t, i){ var key = (i + 1) + '성', picked = gv(key + '특성') || '',
      open = String(gv(key + '해금')).toLowerCase() === 'true';
    // 노드: picked면 .selected, 해금 전·다른 선택은 .locked, 해금+미선택은 .selectable(맥박 애니메이션)
    // 클릭 → 확인 팝업("한번 한 선택은 되돌릴 수 없습니다") → enqueue('cmd', key+' 특성 선택: '+n, '특성선택:'+key+':'+n)
  });
}
```
- 루트마다 상태창 노드를 따로 만들어 해당 루트의 스토리 노드에 연결한다. 공통 부분(헤더, 인물, 기억, 큐)은 같은 코드를 쓰고, 성장 탭과 DB만 바꾼다.
- 되돌릴 수 없는 선택이나 장착 조건(휴식 중에만)은 HTML에서 막고, 변수를 실제로 바꾸는 처리는 업데이트 규칙에 명시한다.
